-- Création de la table des sorts
CREATE TABLE IF NOT EXISTS spells (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    level INTEGER NOT NULL,
    school TEXT,
    casting_time TEXT,
    range TEXT,
    components TEXT,
    duration TEXT,
    combinable INTEGER DEFAULT 0, -- 1 si combinable, 0 sinon
    description TEXT
);

BEGIN TRANSACTION;

-- NIVEAU 0 (Tours de magie)
INSERT INTO spells (name, level, school, casting_time, range, components, duration, combinable, description) VALUES
('Amis', 0, 'enchantement', '1 action', 'personnelle', 'S, M (une petite quantité de maquillage appliquée sur le visage durant l''incantation)', 'concentration, jusqu''à 1 minute', 0, 'Pour la durée du sort, vous avez un avantage à tous vos jets de Charisme effectués contre une créature de votre choix qui n''a pas une attitude hostile envers vous. Lorsque le sort prend fin, la créature réalise que vous avez utilisé la magie pour l''influencer et devient hostile à votre égard. Une créature plutôt violente risque de vous attaquer. D''autres créatures peuvent vous demander de l''argent ou un service (à la discrétion du MD), cela dépend de la nature de l''échange que vous avez eu avec la créature.'),
('Aspersion d''acide', 0, 'invocation', '1 action', '18 mètres', 'V, S', 'instantanée', 0, 'Vous propulsez une bulle d''acide. Choisissez une ou deux créatures que vous pouvez voir, à 1,50 mètre ou moins l''une de l''autre, dans la portée du sort. La cible doit réussir un jet de sauvegarde de Dextérité ou subir 1d6 dégâts d''acide. Les dégâts de ce sort augmentent de 1d6 lorsque vous atteignez le niveau 5 (2d6), le niveau 11 (3d6) et le niveau 17 (4d6).'),
('Assistance', 0, 'divination', '1 action', 'contact', 'V, S', 'concentration, jusqu''à 1 minute', 1, 'Vous touchez une créature consentante. Une fois avant la fin du sort, la cible peut lancer un d4 et ajouter le résultat du dé à un jet de caractéristique de son choix. Elle peut lancer le dé avant ou après avoir effectué son jet de caractéristique. Le sort prend alors fin.'),
('Bouffée de poison', 0, 'invocation', '1 action', '3 mètres', 'V, S', 'instantanée', 0, 'Vous tendez votre paume vers une créature visible dans la portée du sort et vous projetez une bouffée de gaz nocif de votre main. La créature doit réussir un jet de sauvegarde de Constitution ou subir 1d12 dégâts de poison. Les dégâts de ce sort augmentent de 1d12 lorsque vous atteignez le niveau 5 (2d12), le niveau 11 (3d12) et le niveau 17 (4d12).'),
('Contact glacial', 0, 'nécromancie', '1 action', '36 mètres', 'V, S', '1 round', 0, 'Vous créez une main squelettique fantomatique dans l''espace d''une créature à portée. Faites une attaque à distance avec un sort contre la créature pour l''étreindre d''une froideur sépulcrale. Si le coup touche, la cible subit 1d8 dégâts nécrotiques, et elle ne peut récupérer ses points de vie avant le début de votre prochain tour. Jusque-là, la main fantomatique s''accroche à la cible. Si vous ciblez un mort-vivant, il aura également un désavantage à ses jets d''attaque contre vous jusqu''à la fin de votre prochain tour. Les dégâts de ce sort augmentent de 1d8 lorsque vous atteignez le niveau 5 (2d8), le niveau 11 (3d8) et le niveau 17 (4d8).'),
('Contrôle des flammes', 0, 'transmutation', '1 action', '18 mètres', 'S', 'instantanée ou 1 heure (voir ci-dessous)', 1, 'Vous choisissez un feu non magique visible dans la portée du sort de 1,50 mètre d''arête maximum. Vous pouvez l''affecter de l'une des façons suivantes : Vous pouvez faire grossir instantanément le feu de 1,50 mètre dans une direction... Si vous lancez ce sort plusieurs fois, vous pouvez avoir jusqu''à trois de ses effets non-instantanés actifs à la fois, et vous pouvez en dissiper un en une action.'),
('Coup au but', 0, 'divination', '1 action', '9 mètres', 'S', 'concentration, jusqu''à 1 round', 0, 'Vous tendez votre main et pointez un doigt en direction d''une cible à portée. Votre magie vous aide à trouver une petite faille dans les défenses de votre cible. Lors de votre prochain tour, vous obtenez un avantage pour votre premier jet d''attaque contre la cible, à condition que le sort ne soit pas déjà terminé.'),
('Coup de tonnerre', 0, 'évocation', '1 action', '1,50 mètre', 'S', 'instantanée', 0, 'Vous créez un bruit de tonnerre qui peut être entendu jusqu''à 30 mètres. Hormis vous-même, toute créature à portée doit réussir un jet de sauvegarde de Constitution ou subir 1d6 dégâts de tonnerre. Les dégâts de ce sort augmentent de 1d6 lorsque vous atteignez le niveau 5 (2d6), le niveau 11 (3d6) et le niveau 17 (4d6).'),
('Décharge occulte', 0, 'évocation', '1 action', '36 mètres', 'V, S', 'instantanée', 0, 'Un rayon d''énergie crépitante zigzague jusqu''à une créature à portée. Effectuez une attaque à distance avec un sort contre la cible. En cas de réussite, la cible subit 1d10 dégâts de force. Ce sort crée plus d''un rayon lorsque vous montez en niveau : deux rayons au niveau 5, trois rayons au niveau 11, et quatre rayons au niveau 17.'),
('Druidisme', 0, 'transmutation', '1 action', '9 mètres', 'V, S', 'instantanée', 0, 'En murmurant aux esprits de la nature, vous créez l''un des effets suivants, dans la portée du sort : effet sensoriel météo, floraison immédiate, effet sensoriel minime, ou allumer/éteindre une petite flamme.'),
('Éclat gravitationnel', 0, 'inconnu', '1 action', 'm/t du joueur', 'S', '1t', 0, 'Petite poussée qui fait reculer un ennemi de 1,5 m. Niveau supérieur : +0.5m/lv de joueur.'),
('Embrasement', 0, 'invocation', '1 action', '18 mètres', 'V, S', 'concentration, jusqu''à 1 minute', 0, 'Vous créez un feu de joie sur un sol visible dans la portée du sort. Jusqu''à ce que le sort finisse, le feu de joie magique occupe un cube de 1,50 mètre d''arête. Dégâts : 1d8 feu (JS Dex). Augmente au niv 5, 11, 17.'),
('Éruption de lames', 0, 'invocation', '1 action', 'personnelle (rayon de 1,50 mètre)', 'V', 'instantanée', 0, 'Vous créez temporairement un cercle de lames spectrales autour de vous. Toutes les autres créatures dans un rayon de 1,50 mètre doivent réussir un JS Dextérité ou subir 1d6 dégâts de force (augmente au niv 5, 11, 17).'),
('Façonnage de l''eau', 0, 'transmutation', '1 action', '9 mètres', 'S', 'instantanée ou 1 heure', 1, 'Manipulez un cube d''eau de 1,50 m (déplacer, former, changer couleur/opacité, geler). Deux effets non-instantanés max.'),
('Façonnage de la terre', 0, 'transmutation', '1 action', '9 mètres', 'S', 'instantanée ou 1 heure', 1, 'Manipulez la terre/pierre (creuser/déplacer terre meuble, écrire/dessiner, terrain difficile/normal). Deux effets non-instantanés max.'),
('Ferrage foudroyant', 0, 'évocation', '1 action', 'personnelle (rayon de 4,50 mètres)', 'V', 'instantanée', 0, 'Décharge foudroyante attirant une cible sur 3m. JS Force ou subit 1d8 dégâts de foudre si à 1,50m ou moins.'),
('Flamme sacrée', 0, 'évocation', '1 action', '18 mètres', 'V, S', 'instantanée', 0, 'Un rayonnement descend sur une créature visible. JS Dextérité ou 1d8 dégâts radiants (pas de bénéfice d''abri).'),
('Flammes', 0, 'invocation', '1 action', 'personnelle', 'V, S', '10 minutes', 0, 'Produit une flamme dans la main (lumière 3m). Peut être jetée à 9m pour 1d8 dégâts de feu.'),
('Fouet épineux', 0, 'transmutation', '1 action', '9 mètres', 'V, S, M (la tige d''une plante avec des épines)', 'instantanée', 0, 'Attaque au corps à corps avec un sort. 1d6 dégâts perforants et tire la cible de taille G ou inférieure jusqu''à 3m vers vous.'),
('Gelure', 0, 'évocation', '1 action', '18 mètres', 'V, S', 'instantanée', 0, 'Couche de gel. JS Constitution ou 1d6 dégâts de froid et désavantage au prochain jet d''attaque avant la fin du prochain tour.'),
('Glas', 0, 'nécromancie', '1 action', '18 mètres', 'V, S', 'instantanée', 0, 'Son de cloche painful. JS Sagesse ou 1d8 dégâts nécrotiques (1d12 si la cible n''est pas au max de ses PV).'),
('Gourdin magique', 0, 'transmutation', '1 action bonus', 'contact', 'V, S, M (du gui, une feuille de trèfle et un bâton ou un gourdin)', '1 minute', 1, 'Enchante un bâton/gourdin. Permet d''utiliser la caractéristique d''incantation pour l''attaque et les dégâts (d8). L''arme devient magique.'),
('Illusion mineure', 0, 'illusion', '1 action', '9 mètres', 'S, M (un peu de laine de mouton)', '1 minute', 1, 'Crée un son ou l''image d''un objet (cube de 1,50 m max) à portée.'),
('Infestation', 0, 'invocation', '1 action', '9 mètres', 'V, S, M (une puce vivante)', 'instantanée', 0, 'Nuage de parasites. JS Constitution ou 1d6 dégâts de poison et déplacement aléatoire de 1,50 m (d4).'),
('Lame aux flammes vertes', 0, 'évocation', '1 action', 'personnelle (rayon de 1,50 mètre)', 'S, M (une arme de corps à corps valant au moins 1 pa)', 'instantanée', 0, 'Attaque au corps à corps. En cas de touche, inflige les dégâts normaux et saute sur une 2e cible proche pour des dégâts de feu (modificateur d''incantation).'),
('Lame retentissante', 0, 'évocation', '1 action', 'personnelle (rayon de 1,50 mètre)', 'V, M (une arme de corps à corps valant au moins 1 pa)', '1 round', 0, 'Attaque au corps à corps. Enveloppe la cible d''énergie : si elle se déplace volontairement de 1,50 m+, elle subit 1d8 dégâts de tonnerre.'),
('Lumière', 0, 'évocation', '1 action', 'contact', 'V, M (une luciole ou de la mousse phosphorescente)', '1 heure', 1, 'L''objet touché émet une lumière vive sur 6m et faible sur 6m supplémentaires.'),
('Lumières dansantes', 0, 'évocation', '1 action', '36 mètres', 'V, S, M (phosphore, écorce ou ver luisant)', 'concentration, jusqu''à 1 minute', 1, 'Crée jusqu''à 4 lumières de taille torche ou un humanoïde brillant (lumière faible sur 3m).'),
('Main de mage', 0, 'invocation', '1 action', '9 mètres', 'V, S', '1 minute', 1, 'Invoque une main spectrale capable de manipuler des objets (max 5 kg) jusqu''à 9m.'),
